<script>const shell=document.getElementById('app-shell'),toggle=document.getElementById('sidebar-toggle'),sideClose=document.getElementById('sidebar-close'),overlay=document.getElementById('sidebar-overlay');const mobile=()=>window.innerWidth<=960;if(!mobile()&&localStorage.getItem('surya-sidebar-collapsed')==='true')shell.classList.add('sidebar-collapsed');document.documentElement.classList.remove('surya-sidebar-precollapsed');toggle.onclick=()=>{if(mobile()){shell.classList.toggle('sidebar-open')}else{const collapsed=shell.classList.toggle('sidebar-collapsed');localStorage.setItem('surya-sidebar-collapsed',collapsed?'true':'false')}};const closeSide=()=>shell.classList.remove('sidebar-open');sideClose.onclick=closeSide;overlay.onclick=closeSide;window.addEventListener('resize',()=>{if(!mobile())shell.classList.remove('sidebar-open')});const salesByTap=@json($salesByTap);const updateTemplate=@json(route('surya.outlet-list.update',['idOutlet'=>'__ID__']));const modal=document.getElementById('edit-modal');document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{document.getElementById('modal-outlet').textContent=b.dataset.name+' · '+b.dataset.id;const sf=document.getElementById('edit-sf');sf.innerHTML='<option value="UNMAPPING">UNMAPPING</option>';(salesByTap[b.dataset.tap]||[]).forEach(x=>{const o=document.createElement('option');o.value=x.namasf;o.textContent=x.namasf+' ('+x.idsf+')';sf.appendChild(o)});sf.value=b.dataset.sf||'UNMAPPING';document.getElementById('edit-pjp').value=b.dataset.pjp||'UNMAPPING';document.getElementById('edit-form').action=updateTemplate.replace('__ID__',encodeURIComponent(b.dataset.id));modal.classList.add('open')});document.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>modal.classList.remove('open'));modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')}</script>
